  const { entry, fastEvents } = args
  switch (entry.kind) {
    case EEntryKind.OperatorSaid:
      return userItemOf(entry)
    case EEntryKind.AgentSaid:
      return {
        kind: ETranscriptKind.Notice,
        id: entry.key,
        title: `Message from ${entry.sender}`,
        body: entry.text,
        tone: ENoticeTone.Quiet,
