import { archiveExport } from './archive';

export interface Invoice {
  number: string;
  customerId: string;
  issuedAt: Date;
  totalCents: number;
  currency: string;
  lines: InvoiceLine[];
}

export interface InvoiceLine {
  sku: string;
  quantity: number;
  unitPriceCents: number;
}

export interface ExportTemplate {
  render(data: Record<string, unknown>): string;
}

export class Sheet {
  readonly rows: string[][] = [];

  constructor(readonly name: string) {}

  appendRow(cells: string[]): void {
    this.rows.push(cells);
  }

  toJSON(): { name: string; rows: string[][] } {
    return { name: this.name, rows: this.rows };
  }
}

export class Workbook {
  private readonly sheets = new Map<string, Sheet>();

  sheet(name: string): Sheet {
    const existing = this.sheets.get(name);
    if (existing) return existing;
    const created = new Sheet(name);
    this.sheets.set(name, created);
    return created;
  }

  toBuffer(): Buffer {
    const payload = [...this.sheets.values()].map((sheet) => sheet.toJSON());
    return Buffer.from(JSON.stringify(payload), 'utf8');
  }
}

export function formatCents(cents: number, currency: string): string {
  return (cents / 100).toFixed(2) + ' ' + currency;
}

export function invoiceCells(invoices: Invoice[]): string[][] {
  return invoices.map((invoice) => [
    invoice.number,
    invoice.customerId,
    invoice.issuedAt.toISOString().slice(0, 10),
    formatCents(invoice.totalCents, invoice.currency),
  ]);
}

export function assertBatchSize(invoices: Invoice[], limit: number): void {
  if (invoices.length > limit) {
    throw new Error('batch of ' + invoices.length + ' exceeds limit ' + limit);
  }
}

export class InvoiceExporter {
  constructor(private readonly templates: Map<string, ExportTemplate>) {}

  async export(kind: string, invoices: Invoice[]): Promise<Buffer> {
    assertBatchSize(invoices, 500);
    switch (kind) {
      case 'csv': {
        const header = 'number,customer,issued,total';
        const rows = invoiceCells(invoices).map((cells) => cells.join(','));
        return Buffer.from([header, ...rows].join('\n'), 'utf8');
      }
      case 'xlsx': {
        const workbook = new Workbook();
        const sheet = workbook.sheet('invoices');
        sheet.appendRow(['number', 'customer', 'issued', 'total']);
        for (const cells of invoiceCells(invoices)) sheet.appendRow(cells);
        return workbook.toBuffer();
      }
      case 'ledger': {
        const lines = invoices.flatMap((invoice) =>
          invoice.lines.map((line) =>
            [invoice.number, line.sku, line.quantity, formatCents(line.unitPriceCents, invoice.currency)].join(';'),
          ),
        );
        return Buffer.from(lines.join('\n'), 'utf8');
      }
      default:
        throw new Error('unsupported export kind: ' + kind);
    }
  }
}

