export interface NotificationMessage {
  channel: string;
  subject: string;
  body: string;
  recipient: Recipient;
}

export interface DeliveryReceipt {
  channel: string;
  providerId: string;
  acceptedAt: Date;
}

export class DeliveryLog {
  private readonly entries: DeliveryReceipt[] = [];

  record(receipt: DeliveryReceipt): void {
    this.entries.push(receipt);
  }

  forChannel(channel: string): DeliveryReceipt[] {
    return this.entries.filter((entry) => entry.channel === channel);
  }
}

export class RetryPolicy {
  constructor(
    private readonly attempts: number,
    private readonly baseDelayMs: number,
  ) {}

  delayFor(attempt: number): number {
    return this.baseDelayMs * 2 ** attempt;
  }

  shouldRetry(attempt: number): boolean {
    return attempt < this.attempts;
  }
}

export function requireEmail(recipient: Recipient): string {
  if (!recipient.email) throw new Error('recipient has no email address');
  return recipient.email;
}

export function requirePhone(recipient: Recipient): string {
  if (!recipient.phone) throw new Error('recipient has no phone number');
