    return this.prefix + '/' + tenantId + '/';
  }
}

export function checksumOf(bytes: Buffer): string {
  let hash = 0;
  for (const byte of bytes) {
    hash = (hash * 31 + byte) % 2147483647;
  }
  return hash.toString(16).padStart(8, '0');
}

