export interface Column {
  key: string;
  label: string;
  align: 'left' | 'right';
}

export interface Dataset {
  columns: Column[];
  rows: Array<Record<string, string | number>>;
}

export interface RenderedReport {
  mimeType: string;
  bytes: Buffer;
}

export function columnWidths(dataset: Dataset): number[] {
  return dataset.columns.map((column) => {
    const headerWidth = column.label.length;
    const cellWidth = dataset.rows.reduce((max, row) => Math.max(max, String(row[column.key] ?? '').length), 0);
    return Math.max(headerWidth, cellWidth) + 2;
  });
}

export function padCell(value: string | number, width: number, align: 'left' | 'right'): string {
  const text = String(value);
  if (text.length >= width) return text.slice(0, width);
  const padding = ' '.repeat(width - text.length);
  return align === 'right' ? padding + text : text + padding;
}

export class ReportCache {
  private readonly entries = new Map<string, RenderedReport>();

  keyFor(name: string, dataset: Dataset): string {
    return name + ':' + dataset.rows.length + ':' + dataset.columns.length;
  }

  get(name: string, dataset: Dataset): RenderedReport | undefined {
    return this.entries.get(this.keyFor(name, dataset));
  }

  put(name: string, dataset: Dataset, report: RenderedReport): void {
    this.entries.set(this.keyFor(name, dataset), report);
  }
}

declare function datasetToSvg(dataset: Dataset, kind: string): Promise<Buffer>;
declare function datasetToXlsx(dataset: Dataset): Promise<Buffer>;
declare function datasetToPdf(dataset: Dataset): Promise<Buffer>;

export class ReportRenderer {
  constructor(private readonly cache: ReportCache) {}

  async render(kind: string, dataset: Dataset): Promise<RenderedReport> {
    const cached = this.cache.get(kind, dataset);
    if (cached) return cached;
    const widths = columnWidths(dataset);
    switch (kind) {
      case 'table': {
        const border = widths.map((width) => '-'.repeat(width)).join('+');
        const header = dataset.columns.map((column, index) => padCell(column.label, widths[index]!, column.align)).join('|');
        const body = dataset.rows.map((row) =>
          dataset.columns.map((column, index) => padCell(row[column.key] ?? '', widths[index]!, column.align)).join('|'),
        );
        const report = { mimeType: 'text/plain', bytes: Buffer.from([border, header, border, ...body, border].join('\n')) };
        this.cache.put(kind, dataset, report);
        return report;
      }
      case 'chart': {
        const svg = await datasetToSvg(dataset, 'bar');
        const report = { mimeType: 'image/svg+xml', bytes: svg };
        this.cache.put(kind, dataset, report);
        return report;
      }
      case 'pivot': {
        const grouped = new Map<string, number>();
        for (const row of dataset.rows) {
          const key = String(row[dataset.columns[0]?.key ?? ''] ?? '');
          grouped.set(key, (grouped.get(key) ?? 0) + 1);
        }
        const lines = [...grouped.entries()].map((entry) => entry[0] + ',' + entry[1]);
        const report = { mimeType: 'text/csv', bytes: Buffer.from(lines.join('\n'), 'utf8') };
        this.cache.put(kind, dataset, report);
        return report;
      }
      case 'text': {
        const bytes = await datasetToPdf(dataset);
        const report = { mimeType: 'application/pdf', bytes };
        this.cache.put(kind, dataset, report);
        return report;
      }
      default:
        throw new Error('unsupported report kind: ' + kind);
    }
  }
}

