export interface Signal {
  metric: string;
  value: number;
  observedAt: Date;
}

export interface Rule {
  id: string;
  kind: string;
  metric: string;
  threshold: number;
  windowMinutes: number;
}

export interface RuleMatch {
  ruleId: string;
  explanation: string;
  severity: 'low' | 'medium' | 'high';
}

export class SignalWindow {
  private readonly signals: Signal[] = [];

  push(signal: Signal): void {
    this.signals.push(signal);
    const cutoff = signal.observedAt.getTime() - 60 * 60 * 1000;
    while (this.signals.length > 0 && this.signals[0]!.observedAt.getTime() < cutoff) {
      this.signals.shift();
    }
  }

  latest(metric: string): Signal | undefined {
    return [...this.signals].reverse().find((signal) => signal.metric === metric);
  }

  mean(metric: string): number {
    const values = this.signals.filter((signal) => signal.metric === metric).map((signal) => signal.value);
    if (values.length === 0) return 0;
    return values.reduce((sum, value) => sum + value, 0) / values.length;
  }
}

export function severityFor(value: number, threshold: number): 'low' | 'medium' | 'high' {
  const ratio = threshold === 0 ? value : value / threshold;
  if (ratio >= 3) return 'high';
  if (ratio >= 1.5) return 'medium';
  return 'low';
}

export class AlertEvaluator {
  constructor(private readonly window: SignalWindow) {}

  evaluate(rule: Rule): RuleMatch | null {
    if (rule.kind === 'threshold') {
      const signal = this.window.latest(rule.metric);
      if (!signal) return null;
      if (signal.value < rule.threshold) return null;
      return {
        ruleId: rule.id,
        severity: severityFor(signal.value, rule.threshold),
        explanation: rule.metric + ' reached ' + signal.value,
      };
    } else if (rule.kind === 'absence') {
      const signal = this.window.latest(rule.metric);
      const ageMinutes = signal ? (Date.now() - signal.observedAt.getTime()) / 60000 : Number.POSITIVE_INFINITY;
      if (ageMinutes < rule.windowMinutes) return null;
      return {
        ruleId: rule.id,
        severity: 'high',
        explanation: rule.metric + ' silent for ' + Math.round(ageMinutes) + ' minutes',
      };
    } else if (rule.kind === 'deviation') {
      const mean = this.window.mean(rule.metric);
      const signal = this.window.latest(rule.metric);
      if (!signal) return null;
      const drift = mean === 0 ? 0 : Math.abs(signal.value - mean) / mean;
      if (drift < rule.threshold) return null;
      return {
        ruleId: rule.id,
        severity: severityFor(drift, rule.threshold),
        explanation: rule.metric + ' drifted ' + (drift * 100).toFixed(0) + '%',
      };
    }
    return null;
  }
}

