    } else if (rule.kind === 'deviation') {
      const mean = this.window.mean(rule.metric);
      const signal = this.window.latest(rule.metric);
      if (!signal) return null;
      const drift = mean === 0 ? 0 : Math.abs(signal.value - mean) / mean;
      if (drift < rule.threshold) return null;
      return {
        ruleId: rule.id,
        severity: severityFor(drift, rule.threshold),
        explanation: rule.metric + ' drifted ' + (drift * 100).toFixed(0) + '%',
      };
    } else if (rule.kind === 'rate') {
      const mean = this.window.mean(rule.metric);
      if (mean === 0) return null;
      const slope = mean / Math.max(1, rule.windowMinutes);
      if (slope < rule.threshold) return null;
      return {
        ruleId: rule.id,
        severity: severityFor(slope, rule.threshold),
        explanation: rule.metric + ' rising by ' + slope.toFixed(2) + ' per minute',
      };
    }
    return null;
  }
}

