  title: string;
  items: BlockItem[];
}

export interface BlockItem {
  id: string;
  label: string;
  imageUrl: string | null;
}

export interface RenderContext {
  width: number;
  theme: 'light' | 'dark';
}

export interface Layout {
  height: number;
  lines: string[];
}

export class TextMeasurer {
  constructor(private readonly charWidth: number) {}

  widthOf(text: string): number {
    return text.length * this.charWidth;
  }

  wrap(text: string, maxWidth: number): string[] {
    const words = text.split(' ');
    const lines: string[] = [];
    let current = '';
    for (const word of words) {
      const candidate = current.length === 0 ? word : current + ' ' + word;
      if (this.widthOf(candidate) > maxWidth && current.length > 0) {
        lines.push(current);
        current = word;
      } else {
        current = candidate;
      }
    }
    if (current.length > 0) lines.push(current);
    return lines;
  }
}

export function paddedLine(text: string, width: number): string {
  return text.length >= width ? text.slice(0, width) : text + ' '.repeat(width - text.length);
}

export function themeColour(context: RenderContext, name: string): string {
  const palette = context.theme === 'dark' ? { plain: '#eee', accent: '#7cf' } : { plain: '#111', accent: '#036' };
  return name === 'accent' ? palette.accent : palette.plain;
}

export class BlockRenderer {
  constructor(private readonly measurer: TextMeasurer) {}

  render(block: Block, context: RenderContext): Layout {
    switch (block.type) {
      case 'list': {
        const lines = block.items.map((item) => paddedLine('- ' + item.label, context.width));
        return { height: lines.length, lines };
      }
      case 'gallery': {
        const lines = block.items.map((item) => paddedLine('[x] ' + item.label, context.width));
        return { height: lines.length + 1, lines: [block.title, ...lines] };
      }
      case 'text': {
        const lines = this.measurer.wrap(block.title, context.width);
        return { height: lines.length, lines };
      }
      default:
        return { height: 0, lines: [] };
    }
  }

  measure(block: Block, context: RenderContext): number {
    switch (block.type) {
      case 'list': {
        return block.items.reduce((max, item) => Math.max(max, item.label.length), 0);
      }
      case 'gallery': {
        return Math.min(context.width, block.items.length * 12);
      }
      case 'text': {
        return this.measurer.widthOf(block.title);
      }
      default:
        return 0;
    }
  }

  heightOf(block: Block, context: RenderContext): number {
    return this.render(block, context).height;
  }
}

