export interface Filter {
  kind: string;
  field: string;
  value?: string | number;
  values?: Array<string | number>;
  from?: number;
  to?: number;
}

export function quoteIdent(name: string): string {
  return '"' + name.replace(/"/g, '""') + '"';
}

export class FilterCompiler {
  constructor(private readonly table: string) {}

  toSql(filter: Filter): string {
    switch (filter.kind) {
      case 'equals': {
        const column = quoteIdent(filter.field);
        return this.table + '.' + column + ' = :' + filter.field;
      }
      case 'in': {
        const column = quoteIdent(filter.field);
        const placeholders = (filter.values ?? []).map((_value, index) => ':' + filter.field + index);
        return this.table + '.' + column + ' IN (' + placeholders.join(', ') + ')';
      }
      default:
        throw new Error('unsupported filter kind: ' + filter.kind);
    }
  }

  toParams(filter: Filter): Array<string | number> {
    const params: Array<string | number> = [];
    switch (filter.kind) {
      case 'equals': {
        params.push(filter.value ?? '');
        return params;
      }
      case 'in': {
        for (const value of filter.values ?? []) params.push(value);
        return params;
      }
      default:
        throw new Error('unsupported filter kind: ' + filter.kind);
    }
  }

  compile(filters: Filter[]): { where: string; params: Array<string | number> } {
    const where = filters.map((filter) => this.toSql(filter)).join(' AND ');
    const params = filters.flatMap((filter) => this.toParams(filter));
    return { where, params };
  }
}

