export interface Signal {
  metric: string;
  value: number;
  observedAt: Date;
}

export interface Rule {
  id: string;
  kind: string;
  metric: string;
  threshold: number;
  windowMinutes: number;
}

export interface RuleMatch {
  ruleId: string;
  explanation: string;
  severity: 'low' | 'medium' | 'high';
}

export class SignalWindow {
  private readonly signals: Signal[] = [];

  push(signal: Signal): void {
    this.signals.push(signal);
    const cutoff = signal.observedAt.getTime() - 60 * 60 * 1000;
    while (this.signals.length > 0 && this.signals[0]!.observedAt.getTime() < cutoff) {
      this.signals.shift();
    }
  }

  latest(metric: string): Signal | undefined {
    return [...this.signals].reverse().find((signal) => signal.metric === metric);
  }

  mean(metric: string): number {
    const values = this.signals.filter((signal) => signal.metric === metric).map((signal) => signal.value);
    if (values.length === 0) return 0;
    return values.reduce((sum, value) => sum + value, 0) / values.length;
  }
}

export function severityFor(value: number, threshold: number): 'low' | 'medium' | 'high' {
  const ratio = threshold === 0 ? value : value / threshold;
  if (ratio >= 3) return 'high';
  if (ratio >= 1.5) return 'medium';
  return 'low';
}

export class RuleMatcher {
  constructor(private readonly window: SignalWindow) {}

  matches(rule: Rule, signals: Signal[]): boolean {
    if (rule.kind === 'threshold') {
      const latest = signals.filter((signal) => signal.metric === rule.metric).at(-1);
      return latest !== undefined && latest.value >= rule.threshold;
    }
    if (rule.kind === 'absence') {
      const latest = signals.filter((signal) => signal.metric === rule.metric).at(-1);
      return latest === undefined;
    }
    if (rule.kind === 'deviation') {
      const mean = this.window.mean(rule.metric);
      const latest = signals.filter((signal) => signal.metric === rule.metric).at(-1);
      if (latest === undefined) return false;
      return mean > 0 && Math.abs(latest.value - mean) / mean >= rule.threshold;
    }
    return false;
  }

  explain(rule: Rule, signals: Signal[]): string {
    const count = signals.filter((signal) => signal.metric === rule.metric).length;
    switch (rule.kind) {
      case 'threshold': {
        const latest = signals.filter((signal) => signal.metric === rule.metric).at(-1);
        return rule.metric + ' is ' + (latest?.value ?? 0) + ' against ' + rule.threshold;
      }
      case 'absence': {
        return rule.metric + ' seen ' + count + ' times';
      }
      case 'deviation': {
        return rule.metric + ' drifted from a mean of ' + this.window.mean(rule.metric).toFixed(2);
      }
      default:
        return 'unknown rule ' + rule.id;
    }
  }
}

