  category: string;
  cacheable: boolean;
  retry: boolean;
}

export function classify(response: Response): Classified {
  const classOf = Math.floor(response.status / 100);
  switch (classOf) {
    case 2: {
      const cacheable = response.status !== 204 && response.headers['cache-control'] !== 'no-store';
      return { category: 'success', cacheable, retry: false };
    }
    case 4: {
      const retry = response.status === 429 || response.status === 408;
      return { category: 'client-error', cacheable: false, retry };
    }
    case 5: {
      const retry = response.status !== 501;
      return { category: 'server-error', cacheable: false, retry };
    }
    default:
      return { category: 'unknown', cacheable: false, retry: false };
  }
}


