  const normalised = normaliseAll(settings);
  return [...normalised.entries()].map((entry) => entry[0] + '=' + entry[1]).join('; ');
}

export class SettingSnapshot {
  private readonly values = new Map<string, string>();

  constructor(settings: SettingValue[]) {
    for (const setting of settings) {
      this.values.set(setting.key, normaliseSetting(setting));
    }
  }

  get(key: string): string {
    return this.values.get(key) ?? '';
  }

  keys(): string[] {
    return [...this.values.keys()].sort();
  }

  asRecord(): Record<string, string> {
    return Object.fromEntries(this.values);
  }
}

export interface ParquetRequest {
  format: string;
  rows: Array<Record<string, string | number>>;
  compression: string;
}

export class ParquetWriter {
  constructor(private readonly blockSize: number) {}

  async write(request: ParquetRequest): Promise<Buffer> {
    switch (request.format) {
      case 'parquet': {
        const encoded = request.rows.map((row) => JSON.stringify(row));
        return Buffer.from(encoded.join('\n'), 'utf8');
      }
      case 'avro': {
        const schema = Object.keys(request.rows[0] ?? {}).join(',');
        const encoded = [schema, ...request.rows.map((row) => Object.values(row).join(','))];
        return Buffer.from(encoded.join('\n'), 'utf8');
      }
      case 'orc': {
        const blocks: string[] = [];
        for (let index = 0; index < request.rows.length; index += this.blockSize) {
          blocks.push(JSON.stringify(request.rows.slice(index, index + this.blockSize)));
        }
        return Buffer.from(blocks.join('\n'), 'utf8');
      }
      default:
        throw new Error('unsupported format: ' + request.format);
    }
  }

  compressionSuffix(): string {
    return '.' + 'gz';
  }
}


export const SUPPORTED_FORMATS = ['parquet', 'avro', 'orc'];

export interface ParquetManifest {
  format: string;
  blocks: number;
  compression: string;
}

export function manifestFor(request: ParquetRequest, blockSize: number): ParquetManifest {
  return {
    format: request.format,
    blocks: Math.ceil(request.rows.length / Math.max(1, blockSize)),
    compression: request.compression,
  };
}

export function emptyRequest(format: string, compression: string): ParquetRequest {
  return { format, rows: [], compression };
}

export function rowWidth(request: ParquetRequest): number {
  return Object.keys(request.rows[0] ?? {}).length;
}

