export interface FeedbackEntry {
  kind: string;
  score: number;
  comment: string;
}

export interface FeedbackSummary {
  headline: string;
  points: number;
}

export function summariseEntry(entry: FeedbackEntry): FeedbackSummary {
  if (entry.kind === 'bug') {
    const points = entry.score <= 2 ? 3 : 1;
    return { headline: 'bug: ' + entry.comment.slice(0, 60), points };
  } else if (entry.kind === 'praise') {
    const points = entry.score >= 4 ? 2 : 0;
    return { headline: 'praise: ' + entry.comment.slice(0, 60), points };
  } else if (entry.kind === 'request') {
    return { headline: 'request: ' + entry.comment.slice(0, 60), points: 1 };
  }
  return { headline: entry.comment.slice(0, 60), points: 0 };
}

export function summariseAll(entries: FeedbackEntry[]): number {
  return entries.reduce((sum, entry) => sum + summariseEntry(entry).points, 0);
}


export function pointsFor(entries: FeedbackEntry[]): number {
  return entries.reduce((sum, entry) => sum + entry.score, 0);
}

export function worstEntry(entries: FeedbackEntry[]): FeedbackEntry | null {
  if (entries.length === 0) return null;
  return entries.reduce((worst, entry) => (entry.score < worst.score ? entry : worst));
}

export class FeedbackDigest {
  private readonly summaries: FeedbackSummary[] = [];

  add(summary: FeedbackSummary): void {
    this.summaries.push(summary);
  }

  headline(): string {
    return this.summaries
      .map((summary) => summary.headline)
      .slice(0, 5)
      .join(' | ');
  }

  points(): number {
    return this.summaries.reduce((sum, summary) => sum + summary.points, 0);
  }
}

export function averageScore(entries: FeedbackEntry[]): number {
  if (entries.length === 0) return 0;
  return pointsFor(entries) / entries.length;
}

